(7136918, 1093074, 138630, '<td valign="top">Good choice and very well done, Dale.  I love the theme!  Congratulations on a nice finish.</td>', 'Good choice and very well done, Dale.  I love the theme!  Congratulations on a nice finish.', '2013-12-01 09:49:47.000000', NULL, 0),
(7136923, 1093074, 12611, '<td valign="top">Nice work Dale! Congrats on the TT.</td>', 'Nice work Dale! Congrats on the TT.', '2013-12-01 10:16:57.000000', NULL, 0),
(7136945, 1093114, 80096, '<td valign="top">Congrats on your ribbon! That must be me, LOL.. sometimes I feel like that with all these cats we have (10 adopted, 10 to 12 ferals). Yes, we run a TNR program which is quite successful. Love the pic, beautiful cat!</td>', 'Congrats on your ribbon! That must be me, LOL.. sometimes I feel like that with all these cats we have (10 adopted, 10 to 12 ferals). Yes, we run a TNR program which is quite successful. Love the pic, beautiful cat!', '2013-12-01 11:02:12.000000', NULL, 0),
(7137046, 1093114, 60173, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by sfalice:</b></div><hr/><i> Unlike PAUL, I have a complete "like" for the foreground tail.<br/>As well as the rest of your well designed and executed composition.<br/>Nice work. </i></td></tr></table> <br/> <br/>I''m with Alice here, I love the foreground tail. The one I have a problem with is the one from the cat sitting on your head. It''s really more of the butt region I think that bothers me, because it''s too flat. Every other cat in the room is totally believable, but that flat bit on the butt of the one on your head seems off. That is the <u>only</u> issue I see with this image. Everything else is perfectly executed.</td>', 'Originally posted by sfalice: Unlike PAUL, I have a complete "like" for the foreground tail.As well as the rest of your well designed and executed composition.Nice work.   I''m with Alice here, I love the foreground tail. The one I have a problem with is the one from the cat sitting on your head. It''s really more of the butt region I think that bothers me, because it''s too flat. Every other cat in the room is totally believable, but that flat bit on the butt of the one on your head seems off. That is the only issue I see with this image. Everything else is perfectly executed.', '2013-12-01 14:33:11.000000', NULL, 0),
(7137485, 1093075, 96751, '<td valign="top">Hehehe, I hope to someday achieve your shoddyness.  Congrats on the ribbon. Love the location and her total concentration.</td>', 'Hehehe, I hope to someday achieve your shoddyness.  Congrats on the ribbon. Love the location and her total concentration.', '2013-12-02 00:40:33.000000', NULL, 0),
